		main_core.Event.bind(eventTarget, 'change', cancelPendingSelectionRestoreOnSelectChange, true);
		main_core.Event.bind(eventTarget, 'pointermove', scrollbarHandlers.handleMove, true);
		main_core.Event.bind(eventTarget, 'mousemove', scrollbarHandlers.handleMove, true);
		main_core.Event.bind(eventTarget, 'mouseup', scrollbarHandlers.stop, true);
		main_core.Event.bind(eventTarget, 'pointerup', scrollbarHandlers.stop, true);
