			scrollbarHandlers.stop();
			restoreHandlers.cancel();
			unbindBehaviorEvents(eventTarget, mouseDownHandler);
			main_core.Event.unbind(eventTarget, 'input', cancelPendingSelectionRestoreOnSelectChange, true);
			main_core.Event.unbind(eventTarget, 'change', cancelPendingSelectionRestoreOnSelectChange, true);
			main_core.Event.unbind(eventTarget, 'pointermove', scrollbarHandlers.handleMove, true);
			main_core.Event.unbind(eventTarget, 'mousemove', scrollbarHandlers.handleMove, true);
			main_core.Event.unbind(eventTarget, 'mouseup', scrollbarHandlers.stop, true);
			main_core.Event.unbind(eventTarget, 'pointerup', scrollbarHandlers.stop, true);
			main_core.Event.unbind(eventTarget, 'pointercancel', scrollbarHandlers.stop, true);
			main_core.Event.unbind(window, 'blur', scrollbarHandlers.stop);
