	const FRAME_TITLE_ARIA_LABEL_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_FRAME_BLOCK_TITLE_ARIA_LABEL';

	// a phrase that failed to load comes back as null, and NodeTitle reads an empty name as "none"
	function getFrameTitleAriaLabel() {
		return main_core.Loc.getMessage(FRAME_TITLE_ARIA_LABEL_MESSAGE_ID) ?? '';
	}

	// @vue/component
	const EditNodeTitle = {
		name: 'EditNodeTitle',
		components: {
			NodeTitle
		},
		props: {
			/** @type Block */
			block: {
				type: Object,
				required: true
			},
			// only the consumer knows what kind of node it names; a frame keeps the phrase it always had
			ariaLabel: {
				type: String,
				default: getFrameTitleAriaLabel
			}
		},
		setup(props) {
			const {
				makeSnapshot
			} = ui_blockDiagram.useHistory();
			return {
				makeSnapshot,
				nodeTitleEditService: nodeTitleEditServices.get(props.block.id)
			};
		},
		computed: {
			...ui_vue3_pinia.mapState(diagramStore, ['isWriteLocked']),
			// not getBlockUserTitle: a frame title stays visible even when it equals the node type name
			title() {
				return this.block.activity?.Properties?.Title ?? '';
			},
			description() {
				return this.block.activity?.Properties?.EditorComment ?? '';
			},
			isEditing() {
				return this.nodeTitleEditService.isEdit.value;
			},
			nodeTypeTitle() {
				return this.block.node?.title ?? '';
			},
			// the own phrase of the node may be missing too: then the title names itself, the way
			// NodeTitle does it for an empty name, and never borrows the phrase of a frame
			titleAriaLabel() {
				return this.ariaLabel ?? '';
			}
		},
		beforeUnmount() {
			nodeTitleEditServices.delete(this.block.id);
		},
		methods: {
			...ui_vue3_pinia.mapActions(diagramStore, ['updateBlockActivityField', 'beginSaveRun', 'publicDraft', 'updateStatus']),
			// The title of a frame is edited by a double click on it, so the ban cannot be left to the
			// context menu the lock already trims.
			onEditRequest() {
				if (this.isWriteLocked) {
					return;
				}
				this.nodeTitleEditService.startEdit();
			},
			async onConfirm(title) {
				// a node cannot stay unnamed: an empty title falls back to the node type name
				const newTitle = title === '' ? this.nodeTypeTitle : title;
				if (newTitle === this.title) {
					this.nodeTitleEditService.confirm();
					return;
				}
				this.updateBlockActivityField(this.block.id, {
					...this.block.activity,
					Properties: {
						...this.block.activity?.Properties,
						Title: newTitle
					}
				});
				this.nodeTitleEditService.confirm();
				this.makeSnapshot();

				// Reserved before the request: a save started after this one owns the status, so a
				// late answer here must not overwrite it. The draft also comes back unsaved without
				// an exception — a deleted template, a lost write access — and such an answer must
				// not leave "Saved" on the screen.
				const runId = this.beginSaveRun();
				try {
					this.updateStatus(await this.publicDraft(), runId);
				} catch {
					this.updateStatus(false, runId);
				}
			}
		},
		template: `
		<NodeTitle
			:blockId="block.id"
			:title="title"
			:description="description"
			:editing="isEditing"
			:ariaLabel="titleAriaLabel"
			@editRequest="onEditRequest"
			@confirm="onConfirm"
			@cancel="nodeTitleEditService.cancel()"
		/>
	`
	};

